/* Vệt mờ trên hàng chip .seg: .more-start / .more-end khi còn nội dung bị cuộn khuất ở đầu / cuối dòng (RTL: scrollLeft ≤ 0, đầu dòng ở bên phải) */
function wireSegFade() {
  const seg = document.querySelector<HTMLElement>('.seg');
  if (!seg) return;
  const update = () => {
    const max = seg.scrollWidth - seg.clientWidth;
    const pos = Math.abs(seg.scrollLeft);   // quãng đã cuộn từ đầu dòng, đúng cả LTR lẫn RTL
    seg.classList.toggle('more-start', ui.compact && pos > 8);
    seg.classList.toggle('more-end', ui.compact && max - pos > 8);
  };
  seg.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', update);
  segFadeUpdate = update;
  if (typeof ResizeObserver !== 'undefined') new ResizeObserver(update).observe(seg);
  onChange(update);   // đổi ngôn ngữ đổi bề rộng chip nhưng không đổi hộp .seg nên ResizeObserver không báo
}
let segFadeUpdate = () => {};

/* Tour / kịch bản bão bật lên thì đóng tờ đang mở (class của body đổi) */
function wireAutoClose() {
  let was = false;
  new MutationObserver(() => {
    const on = document.body.classList.contains('touring') || document.body.classList.contains('wxrun');
    if (on && !was && ui.sheet !== 'none') closeSheets();
    was = on;
  }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
}

export function setupCompactUI() {
  wireSheets();
  wireSegFade();
  wireAutoClose();
  const mq = window.matchMedia(CONFIG.ui.compactQuery);
  const apply = () => {
    const was = ui.compact;
    ui.compact = mq.matches;
    document.body.classList.toggle('compact', ui.compact);
    if (was && !ui.compact) closeSheets();   // ra khỏi chế độ gọn: không để tờ mở dở
    segFadeUpdate();
  };
  mq.addEventListener('change', apply);
  apply();
}
import { CONFIG } from '../config';

export interface DonateApi { set(url: string): boolean }

/* ===== Buy me a coffee (MoMo) ===== */
export function setupDonateUI(): DonateApi {
  const link = document.getElementById('donateLink') as HTMLAnchorElement;
  const set = (url: string) => {
    try {
      if (new URL(url).protocol === 'https:') {
        link.href = url; link.hidden = false; return true;
      }
    } catch { /* URL rỗng hoặc sai định dạng thì ẩn liên kết */ }
    link.removeAttribute('href'); link.hidden = true; return false;
  };
  set(CONFIG.ui.donate.url);
  return { set };
}
import { t, onChange } from '../i18n';
import { quality, type QualityMode } from '../core/quality';

const TIER_KEY = { high: 'qHigh', medium: 'qMed', low: 'qLow' } as const;

/* Ô "Chất lượng hình" (D-018): Tự động / Cao / Trung bình / Thấp. Ở chế độ Tự động, chữ của lựa chọn ghi kèm mức đang dùng ("Tự động · Trung bình") */
export function setupQualityUI() {
  const sel = document.getElementById('qualitySel') as HTMLSelectElement, auto = sel.querySelector<HTMLOptionElement>('option[value="auto"]');
  sel.value = quality.mode;
  sel.addEventListener('change', () => quality.set(sel.value as QualityMode));
  let shown = '';
  const label = () => {
    const txt = quality.mode === 'auto' ? `${t('qAuto')} · ${t(TIER_KEY[quality.current().tier as keyof typeof TIER_KEY])}` : t('qAuto');
    if (txt !== shown) { auto.textContent = txt; shown = txt; }
  };
  onChange(() => { shown = ''; label(); });
  setInterval(label, 1000);   // bậc Tự động đổi tối đa mỗi vài giây: cập nhật chữ 1 lần/giây là đủ
  label();
}
