  const t=fs.readFileSync(f,"utf8");
  for (const m of t.matchAll(/\]\(([^)#\s]+)(#[^)]*)?\)/g)) {
    const u=m[1]; if (/^(https?:|mailto:)/.test(u)) continue;
    if (!fs.existsSync(p.resolve(p.dirname(f),decodeURI(u)))) console.log(f+": "+u);
  }
}' docs/superpowers/specs/2026-10-24-toi-uu-do-muot-design.md docs/superpowers/specs/2026-10-26-mobile-ui-design.md docs/superpowers/specs/2026-10-29-buy-me-a-coffee-design.md docs/superpowers/plans/2026-10-24-toi-uu-do-muot.md docs/superpowers/plans/2026-10-26-mobile-ui.md docs/superpowers/plans/2026-10-29-buy-me-a-coffee.md; echo K2 done
echo NUMS; for n in "11 607" "12 577" "5 528" "7 477" "4 606" "4 176" "3 699" "2 909"; do :; done
sed -n 20,31p .github/memory-bank/activeContext.md | grep -o "[0-9][0-9 ,.]*[0-9]" | sort -u | tr '\n' ' '

